python
def positiveTraysProofStrip(readings, k):
    a=readings
    out=[]
    for x in a:
        if x>0: out.append(x)
    return out


java
class Solution {
  public int[] positiveTraysProofStrip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a)if(x>0)out.add(x);}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
